import{_ as a,o as i,c as t,a2 as s}from"./chunks/framework.DT_qyuxR.js";const g=JSON.parse('{"title":"Effets spéciaux","description":"","frontmatter":{},"headers":[],"relativePath":"gitbook/regles/07-effets-speciaux.md","filePath":"gitbook/regles/07-effets-speciaux.md"}'),r={name:"gitbook/regles/07-effets-speciaux.md"};function n(o,e,l,u,c,d){return i(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="effets-speciaux" tabindex="-1">Effets spéciaux <a class="header-anchor" href="#effets-speciaux" aria-label="Permalink to &quot;Effets spéciaux&quot;">​</a></h1><p>Carnival of the Deads comporte plusieurs effets spéciaux qui sortent des mécaniques classiques.</p><h2 id="malediction-regard-noir" tabindex="-1">Malédiction (Regard Noir) <a class="header-anchor" href="#malediction-regard-noir" aria-label="Permalink to &quot;Malédiction (Regard Noir)&quot;">​</a></h2><p><strong>Porteur</strong> : Abysse <strong>Activation</strong> : une fois par partie, pendant la Nuit <strong>Cible</strong> : un joueur choisi</p><h3 id="mecanique" tabindex="-1">Mécanique <a class="header-anchor" href="#mecanique" aria-label="Permalink to &quot;Mécanique&quot;">​</a></h3><p>Quand l&#39;Abysse utilise Regard Noir sur un joueur :</p><ol><li>Si le joueur <strong>n&#39;est pas de son camp</strong> (différent Vivant/Revenant), la Malédiction est appliquée.</li><li>Si le joueur <strong>est de son camp</strong>, rien ne se passe (la capacité est quand même consommée).</li></ol><h3 id="effet-de-la-malediction" tabindex="-1">Effet de la Malédiction <a class="header-anchor" href="#effet-de-la-malediction" aria-label="Permalink to &quot;Effet de la Malédiction&quot;">​</a></h3><p>Un joueur maudit <strong>ne peut plus changer de salon vocal</strong> pour le reste de la partie. Il est littéralement figé dans sa position.</p><h3 id="strategie" tabindex="-1">Stratégie <a class="header-anchor" href="#strategie" aria-label="Permalink to &quot;Stratégie&quot;">​</a></h3><ul><li><strong>Pour le porteur</strong> : cibler un joueur soupçonné d&#39;être Revenant (ou un Vivant dangereux). Si la Malédiction prend, le joueur est immobilisé et plus facile à localiser.</li><li><strong>Pour la cible</strong> : la Malédiction est une sentence. Un joueur maudit dans le mauvais salon est vulnérable aux attaques du Poursuite (Traque) et du Sacrifice (Percée).</li></ul><h3 id="limites" tabindex="-1">Limites <a class="header-anchor" href="#limites" aria-label="Permalink to &quot;Limites&quot;">​</a></h3><ul><li>Une seule utilisation par partie.</li><li>Ne fonctionne que sur des joueurs de camp <strong>différent</strong>.</li><li>Pas de protection possible (l&#39;Immunité du Chirurgical ne fonctionne pas contre les effets spéciaux).</li></ul><h2 id="metamorphose-mille-visages" tabindex="-1">Métamorphose (Mille Visages) <a class="header-anchor" href="#metamorphose-mille-visages" aria-label="Permalink to &quot;Métamorphose (Mille Visages)&quot;">​</a></h2><p><strong>Porteur</strong> : Sans-Visage <strong>Activation</strong> : chaque nuit <strong>Cible</strong> : un masque choisi</p><h3 id="mecanique-1" tabindex="-1">Mécanique <a class="header-anchor" href="#mecanique-1" aria-label="Permalink to &quot;Mécanique&quot;">​</a></h3><p>Chaque nuit, le Sans-Visage peut choisir un masque et se <strong>métamorphoser</strong> en lui :</p><ol><li><strong>Identification</strong> : les pouvoirs qui voient le masque (comme l&#39;Identification) identifieront le Sans-Visage comme le masque copié.</li><li><strong>Révélation au K.O.</strong> : si le masque du Sans-Visage se brise, c&#39;est le <strong>masque copié</strong> qui est révélé à la place de son identité réelle.</li><li><strong>Persistance</strong> : le déguisement persiste jusqu&#39;au choix suivant (chaque nuit, le Sans-Visage peut changer de masque copié).</li></ol><h3 id="strategie-1" tabindex="-1">Stratégie <a class="header-anchor" href="#strategie-1" aria-label="Permalink to &quot;Stratégie&quot;">​</a></h3><ul><li><strong>Tromper l&#39;information</strong> : si quelqu&#39;un utilise l&#39;Identification sur vous, il verra le masque copié, pas votre vrai masque.</li><li><strong>Protéger votre identité</strong> : au K.O., c&#39;est un autre masque qui est révélé, pas le vôtre. Les joueurs ne sauront pas qui vous étiez vraiment.</li><li><strong>Confusion</strong> : si vous copiez un masque déjà en jeu, les joueurs penseront qu&#39;il y a deux exemplaires de ce masque.</li></ul><h3 id="limites-1" tabindex="-1">Limites <a class="header-anchor" href="#limites-1" aria-label="Permalink to &quot;Limites&quot;">​</a></h3><ul><li>Le déguisement ne change pas vos PV, vos capacités ou votre passif. Vous gardez toujours votre vrai masque.</li><li>La Métamorphose est résolue en <strong>premier</strong> dans l&#39;ordre de résolution (order 1) pour permettre les combos.</li></ul><h2 id="rumeurs-derniere-parole" tabindex="-1">Rumeurs (dernière parole) <a class="header-anchor" href="#rumeurs-derniere-parole" aria-label="Permalink to &quot;Rumeurs (dernière parole)&quot;">​</a></h2><p><strong>Porteur</strong> : tout joueur K.O. <strong>Activation</strong> : automatique au K.O. <strong>Message</strong> : 200 caractères maximum</p><h3 id="mecanique-2" tabindex="-1">Mécanique <a class="header-anchor" href="#mecanique-2" aria-label="Permalink to &quot;Mécanique&quot;">​</a></h3><p>Quand un masque se brise, le joueur peut laisser une <strong>dernière rumeur</strong> avant de quitter le bal. C&#39;est un message public de 200 caractères maximum qui sera affiché dans le salon général.</p><h3 id="strategie-2" tabindex="-1">Stratégie <a class="header-anchor" href="#strategie-2" aria-label="Permalink to &quot;Stratégie&quot;">​</a></h3><ul><li><strong>Pour les Vivants</strong> : laisser un indice sur un Revenant suspect (mais les Revenants peuvent mentir).</li><li><strong>Pour les Revenants</strong> : accuser un faux Revenant pour créer la confusion.</li><li><strong>Pour tous</strong> : la rumeur est une arme à double tranchant. Un menteur peut vous tromper depuis la tombe.</li></ul><h3 id="limites-2" tabindex="-1">Limites <a class="header-anchor" href="#limites-2" aria-label="Permalink to &quot;Limites&quot;">​</a></h3><ul><li>Un seul message de 200 caractères.</li><li>Le joueur K.O. ne peut plus interagir après la rumeur.</li><li>Le contenu n&#39;est pas vérifié — mentir est permis.</li></ul><h2 id="vengeance-lien-familial-du-foyer" tabindex="-1">Vengeance (Lien Familial du Foyer) <a class="header-anchor" href="#vengeance-lien-familial-du-foyer" aria-label="Permalink to &quot;Vengeance (Lien Familial du Foyer)&quot;">​</a></h2><p><strong>Porteur</strong> : Foyer <strong>Activation</strong> : au K.O. de l&#39;Enfant <strong>Effet</strong> : -6 dégâts au responsable</p><h3 id="mecanique-3" tabindex="-1">Mécanique <a class="header-anchor" href="#mecanique-3" aria-label="Permalink to &quot;Mécanique&quot;">​</a></h3><ol><li><strong>Désignation</strong> (Nuit 1) : le Foyer choisit un joueur qui devient son Enfant.</li><li><strong>Lien Familial</strong> (passif) : tant que l&#39;Enfant n&#39;est pas K.O., les attaques de combat du Foyer infligent leurs dégâts <strong>deux fois</strong>.</li><li><strong>Vengeance</strong> : si le masque de l&#39;Enfant se brise, le Foyer inflige <strong>6 dégâts</strong> à celui qui a mis l&#39;Enfant K.O.</li></ol><h3 id="strategie-3" tabindex="-1">Stratégie <a class="header-anchor" href="#strategie-3" aria-label="Permalink to &quot;Stratégie&quot;">​</a></h3><ul><li><strong>Pour le Foyer</strong> : choisir un allié fiable comme Enfant. Si l&#39;Enfant meurt, la vengeance est dévastatrice.</li><li><strong>Pour les adversaires</strong> : tuer l&#39;Enfant du Foyer est risqué — vous subissez 6 dégâts. Vaut mieux éliminer le Foyer directement.</li></ul><h3 id="limites-3" tabindex="-1">Limites <a class="header-anchor" href="#limites-3" aria-label="Permalink to &quot;Limites&quot;">​</a></h3><ul><li>Un seul Enfant par partie.</li><li>La vengeance ne se déclenche que si l&#39;Enfant est mis K.O. par un autre joueur (pas par un effet de nuit).</li><li>Le passif Lien Familial (double dégâts) est conditionnel à la vie de l&#39;Enfant.</li></ul>',38)])])}const p=a(r,[["render",n]]);export{g as __pageData,p as default};
